// Expected values below were recorded on real Fastly edge nodes. Each row names
// the fiddle and the response header (x-cNNN / x-lNNN) that carried its result.
// Inputs were passed as VCL long strings {"..."}, which are not percent-decoded
// at compile time, so they reach the function byte for byte as written here.

const (
	qsENC    = "/p?a=x+y&b=x%20y&c=x y&d=%2B&e=%2b&f=%41%7e&g=~-._*&h=!$'()*,;:@/?"
	qsKEYS   = "/p?k%20v=1&k+v=2&k v=3&%41=4&A=5&%2b=6&%2B=7&+=8&k%2Fv=9&k/v=10&k~v=11&k%7Ev=12"
	qsMAL    = "/p?a=%&b=%G1&c=%2&%=4&%G1=5&d=%zz&e=1%2"
	qsMAL2   = "/p?x=1&%2"
	qsDUP    = "/p?a=1&a=2&a&a=&b=3&=x&=&&c&"
	qsDUP2   = "/p?&a=1&&b&=&"
	qsNOQ    = "/p"
	qsBARE   = "/p?"
	qsAMP    = "/p?&"
	qsFRAG1  = "/p?a=1#frag&b=2"
	qsFRAG2  = "/p#frag?a=1"
	qsFRAG3  = "/p?#f"
	qsQQ     = "/p?a=1?b=2&c=3"
	qsEQ     = "/p?a==1&b=x=y&=&c="
	qsCASE   = "/p?A=1&a=2&aB=3"
	qsUTF    = "/p?é=1&%C3%A9=2&x=é"
	qsGLOBQ  = "/p?k*=1&k?=2&k=3&kk=4&{k,A}=5&[k]=6&\\=7&.h=8&a/b=9&é=10&K=11&k\\=12&k[=13&kA=14"
	qsGLOBQ2 = "/p?k=1&K=2&9=3&-=4&]=5&a-=6&z=7&\\k=8&ab=9&[=10&é=11&!=12&b=13"
	qsREQ    = "/p?k=1&a=2&kx=3"
)

var querystringFuncs = map[string]func(*context.Context, ...value.Value) (value.Value, error){
	"add":               Querystring_add,
	"clean":             Querystring_clean,
	"filter":            Querystring_filter,
	"filter_except":     Querystring_filter_except,
	"get":               Querystring_get,
	"globfilter":        Querystring_globfilter,
	"globfilter_except": Querystring_globfilter_except,
	"regfilter":         Querystring_regfilter,
	"regfilter_except":  Querystring_regfilter_except,
	"remove":            Querystring_remove,
	"set":               Querystring_set,
	"sort":              Querystring_sort,
}

func callQuerystring(t *testing.T, fn string, args []value.Value) *value.String {
	t.Helper()
	f, ok := querystringFuncs[fn]
	if !ok {
		t.Fatalf("unknown function %s", fn)
	}
	ret, err := f(&context.Context{}, args...)
	if err != nil {
		t.Fatalf("querystring.%s returned error: %s", fn, err)
	}
	return value.Unwrap[*value.String](ret)
}

func describeArgs(args []value.Value) string {
	parts := make([]string, len(args))
	for i, a := range args {
		if s, ok := a.(*value.String); ok {
			parts[i] = fmt.Sprintf("%q", s.Value)
		} else {
			parts[i] = a.String()
		}
	}
	return strings.Join(parts, ", ")
}

// pcreEmptyMatch marks rows where falco still differs from Fastly because the
// go-pcre wrapper never reports a match that is empty (it skips a leading empty
// match and returns nil for an empty subject). On Fastly a pattern such as "^",
// "$", "\b" or "(?=k)" matches a name wherever it finds an empty match; in
// falco an empty match never counts.
// The builtins special-case the empty pattern; the general fix belongs in the
// wrapper. https://fiddle.fastly.dev/fiddle/1cb2a444
const pcreEmptyMatch = "go-pcre ignores empty regex matches"

