	for i, tt := range tests {
		t.Run(fmt.Sprintf("%03d_%s", i, tt.fn), func(t *testing.T) {
			got := callQuerystring(t, tt.fn, tt.args)
			sum := md5.Sum([]byte(got.Value))
			if len(got.Value) != tt.wantLen || hex.EncodeToString(sum[:]) != tt.wantMD5 {
				head := got.Value
				if len(head) > 80 {
					head = head[:80] + "..."
				}
				t.Errorf("querystring.%s: want len %d md5 %s, got len %d md5 %x (%s)", tt.fn, tt.wantLen, tt.wantMD5, len(got.Value), sum, head)
			}
		})
	}
